//! Each test gets an isolated PostgreSQL database with real migrations and seeded fixtures.
//! DATABASE_URL must be a PostgreSQL role allowed to create test databases. No mocks replace policy SQL.
use axum::{body::Body,http::{Request,StatusCode},Router};
use http_body_util::BodyExt;
use purrsonnel_api::{app,config::Config,AppState};
use serde_json::{json,Value};
use sqlx::PgPool;
use tower::ServiceExt;
use uuid::Uuid;
#[path="cases/follow_through.rs"] mod follow_through;
struct Harness{db:PgPool,router:Router}
#[derive(Clone)]struct Session{cookie:String,csrf:String}
impl Harness{
 async fn new(db:PgPool)->Self{sqlx::query("SELECT seed_development()").execute(&db).await.unwrap();let router=app::router(AppState::new(sea_orm::SqlxPostgresConnector::from_sqlx_postgres_pool(db.clone()),Config{dev_auth:true,origin:"http://localhost:5173".into(),bind:"127.0.0.1:3000".into(),default_user:"dev.hr@purrsonnel.local".into(),max_volunteer_minutes:960}));Self{db,router}}
 async fn request(&self,method:&str,path:&str,session:Option<&Session>,body:Value)->(StatusCode,Value,Option<String>){let mut req=Request::builder().method(method).uri(format!("/api/v1{path}")).header("host","localhost:5173").header("origin","http://localhost:5173").header("content-type","application/json");if let Some(s)=session{req=req.header("cookie",&s.cookie).header("x-csrf-token",&s.csrf);}let response=self.router.clone().oneshot(req.body(if method=="GET"{Body::empty()}else{Body::from(body.to_string())}).unwrap()).await.unwrap();let status=response.status();let cookie=response.headers().get("set-cookie").map(|v|v.to_str().unwrap().split(';').next().unwrap().to_owned());let bytes=response.into_body().collect().await.unwrap().to_bytes();let value=serde_json::from_slice(&bytes).unwrap_or(Value::Null);(status,value,cookie)}
 async fn login(&self)->Session{let(status,b,c)=self.request("POST","/auth/dev/bootstrap",None,json!({})).await;assert_eq!(status,StatusCode::OK,"{b}");Session{cookie:c.unwrap(),csrf:b["csrf_token"].as_str().unwrap().into()}}
 async fn id(&self,email:&str)->Uuid{sqlx::query_scalar("SELECT id FROM users WHERE email=$1").bind(format!("dev.{email}@purrsonnel.local")).fetch_one(&self.db).await.unwrap()}
 async fn dept(&self,name:&str)->Uuid{sqlx::query_scalar("SELECT id FROM departments WHERE name=$1").bind(name).fetch_one(&self.db).await.unwrap()}
 async fn switch(&self,session:&Session,name:&str)->Session{let id=self.id(name).await;let(status,b,c)=self.request("POST","/auth/dev/switch",Some(session),json!({"user_id":id})).await;assert_eq!(status,StatusCode::OK,"{b}");Session{cookie:c.unwrap(),csrf:b["csrf_token"].as_str().unwrap().into()}}
 async fn submitted(&self,user:Uuid,dept:Uuid)->Uuid{sqlx::query_scalar("INSERT INTO volunteer_entries(volunteer_user_id,department_id,work_date,minutes_worked,work_description,status) VALUES($1,$2,current_date,90,'Test volunteer activity','submitted') RETURNING id").bind(user).bind(dept).fetch_one(&self.db).await.unwrap()}
}

#[sqlx::test(migrations="./migrations")]async fn auto_login_persists_and_does_not_expose_session_token(db:PgPool){let h=Harness::new(db).await;let s=h.login().await;let(status,b,_)=h.request("GET","/auth/me",Some(&s),Value::Null).await;assert_eq!(status,StatusCode::OK);assert_eq!(b["user"]["display_name"],"Juniper Fox");assert!(b["grants"].as_array().unwrap().iter().any(|g|g["permission"]=="people.bulk_update"));assert!(!b.to_string().contains(&s.cookie));let(_,_,cookie)=h.request("POST","/auth/dev/bootstrap",Some(&s),json!({})).await;assert!(cookie.is_none());}
#[sqlx::test(migrations="./migrations")]async fn cookies_have_required_security_flags(db:PgPool){let h=Harness::new(db).await;let req=Request::builder().method("POST").uri("/api/v1/auth/dev/bootstrap").header("host","localhost:5173").header("origin","http://localhost:5173").body(Body::empty()).unwrap();let r=h.router.oneshot(req).await.unwrap();let cookie=r.headers()["set-cookie"].to_str().unwrap();for value in ["HttpOnly","SameSite=Lax","Path=/","Max-Age=43200"]{assert!(cookie.contains(value));}}
#[sqlx::test(migrations="./migrations")]async fn bootstrap_rejects_cross_origin_and_rebinding(db:PgPool){let h=Harness::new(db).await;for(host,origin)in[("localhost:5173","http://evil.example"),("evil.example","http://localhost:5173")]{let r=h.router.clone().oneshot(Request::builder().method("POST").uri("/api/v1/auth/dev/bootstrap").header("host",host).header("origin",origin).body(Body::empty()).unwrap()).await.unwrap();assert_eq!(r.status(),StatusCode::FORBIDDEN);}}
#[sqlx::test(migrations="./migrations")]async fn mutations_reject_missing_csrf(db:PgPool){let h=Harness::new(db).await;let mut s=h.login().await;s.csrf.clear();let(status,_,_)=h.request("POST","/auth/dev/switch",Some(&s),json!({"user_id":h.id("volunteer").await})).await;assert_eq!(status,StatusCode::FORBIDDEN);}
#[sqlx::test(migrations="./migrations")]async fn switch_rotates_session_and_retains_permission_checks(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let vol=h.switch(&hr,"volunteer").await;assert_ne!(hr.cookie,vol.cookie);assert_eq!(h.request("GET","/auth/me",Some(&hr),Value::Null).await.0,StatusCode::UNAUTHORIZED);for path in ["/audit-events","/bulk-changes","/permission-grants"]{assert_eq!(h.request("GET",path,Some(&vol),Value::Null).await.0,StatusCode::FORBIDDEN);}assert_eq!(h.request("POST","/positions",Some(&vol),json!({"title":"No","department_id":h.dept("Registration").await,"position_level_id":Uuid::new_v4(),"is_leadership":false,"description_markdown":"No","hiring_owner_user_id":h.id("volunteer").await,"status":"open"})).await.0,StatusCode::FORBIDDEN);}
#[sqlx::test(migrations="./migrations")]async fn multiple_memberships_and_service_year_gaps(db:PgPool){let h=Harness::new(db).await;let s=h.login().await;let id=h.id("staff").await;for dept in ["Registration","Programming"]{let(_,b,_)=h.request("GET",&format!("/users?department={}",h.dept(dept).await),Some(&s),Value::Null).await;assert!(b["items"].as_array().unwrap().iter().any(|u|u["id"]==id.to_string()));}let(_,b,_)=h.request("GET",&format!("/users/{id}"),Some(&s),Value::Null).await;assert_eq!(b["verified_years"],3);assert_eq!(b["service_years"],json!([2021,2023,2025]));let hr=h.id("hr").await;let(_,b,_)=h.request("GET",&format!("/users/{hr}"),Some(&s),Value::Null).await;assert_eq!(b["verified_years"],2);}
#[sqlx::test(migrations="./migrations")]async fn lead_scope_does_not_leak_outside_departments(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let lead=h.switch(&hr,"lead").await;let target=h.id("staff2").await;assert_eq!(h.request("GET",&format!("/users/{target}"),Some(&lead),Value::Null).await.0,StatusCode::FORBIDDEN);let(_,b,_)=h.request("GET","/users",Some(&lead),Value::Null).await;assert!(!b["items"].as_array().unwrap().iter().any(|u|u["id"]==target.to_string()));}
#[sqlx::test(migrations="./migrations")]async fn director_has_no_implicit_admin(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let d=h.switch(&hr,"director").await;assert_eq!(h.request("GET","/permission-grants",Some(&d),Value::Null).await.0,StatusCode::FORBIDDEN);assert_eq!(h.request("GET","/audit-events",Some(&d),Value::Null).await.0,StatusCode::FORBIDDEN);}
#[sqlx::test(migrations="./migrations")]async fn manager_cycle_is_rejected_and_directs_are_inverse(db:PgPool){let h=Harness::new(db).await;let s=h.login().await;let lead=h.id("lead").await;let staff=h.id("staff").await;assert_eq!(h.request("PATCH",&format!("/users/{lead}"),Some(&s),json!({"manager_id":staff})).await.0,StatusCode::BAD_REQUEST);let(_,b,_)=h.request("GET",&format!("/users/{lead}/directs"),Some(&s),Value::Null).await;assert!(b.as_array().unwrap().iter().any(|u|u["id"]==staff.to_string()));}
#[sqlx::test(migrations="./migrations")]async fn years_are_idempotent_and_corrections_audited(db:PgPool){let h=Harness::new(db).await;let s=h.login().await;let id=h.id("staff").await;for _ in 0..2{assert_eq!(h.request("PUT",&format!("/users/{id}/service-years/2023"),Some(&s),json!({"verification_status":"verified"})).await.0,StatusCode::OK);}let n:i64=sqlx::query_scalar("SELECT count(*) FROM user_service_years WHERE user_id=$1").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(n,3);let n:i64=sqlx::query_scalar("SELECT count(*) FROM audit_events WHERE resource_id=$1 AND action='service_year.recorded'").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(n,2);}
#[sqlx::test(migrations="./migrations")]async fn lead_can_mark_team_activity_and_only_active_members_receive_verified_years(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let lead=h.switch(&hr,"lead").await;let department=h.dept("Registration").await;let lead_id=h.id("lead").await;assert_eq!(h.request("GET",&format!("/departments/{department}/members"),Some(&lead),Value::Null).await.0,StatusCode::OK);assert_eq!(h.request("PATCH",&format!("/departments/{department}/members/{lead_id}"),Some(&lead),json!({"membership_status":"inactive"})).await.0,StatusCode::OK);let hr=h.login().await;assert_eq!(h.request("PUT",&format!("/users/{lead_id}/service-years/2026"),Some(&hr),json!({"verification_status":"verified"})).await.0,StatusCode::BAD_REQUEST);let lead=h.switch(&hr,"lead").await;assert_eq!(h.request("PATCH",&format!("/departments/{department}/members/{lead_id}"),Some(&lead),json!({"membership_status":"active"})).await.0,StatusCode::OK);let hr=h.login().await;assert_eq!(h.request("PUT",&format!("/users/{lead_id}/service-years/2026"),Some(&hr),json!({"verification_status":"verified"})).await.0,StatusCode::OK);}
#[sqlx::test(migrations="./migrations")]async fn multiple_terms_are_independent_and_signing_is_idempotent(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let v=h.switch(&hr,"volunteer").await;let(_,terms,_)=h.request("GET","/terms/applicable",Some(&v),Value::Null).await;assert_eq!(terms.as_array().unwrap().len(),2);let id=terms[0]["version_id"].as_str().unwrap();let signed=json!({"typed_name":"Maple Bunny","consent":true,"answers":{},"signature_svg":"<svg><path d=\"M 0,0 L 1,1\"/></svg>"});for _ in 0..2{assert_eq!(h.request("POST",&format!("/term-versions/{id}/sign"),Some(&v),signed.clone()).await.0,StatusCode::OK);}let(_,terms,_)=h.request("GET","/terms/applicable",Some(&v),Value::Null).await;assert_eq!(terms.as_array().unwrap().iter().filter(|t|!t["signed_at"].is_null()).count(),1);assert_eq!(h.request("POST",&format!("/term-versions/{id}/sign"),Some(&v),json!({"typed_name":"Maple Bunny","consent":false,"answers":{},"signature_svg":"<svg><path d=\"M 0,0 L 1,1\"/></svg>"})).await.0,StatusCode::BAD_REQUEST);}
#[sqlx::test(migrations="./migrations")]async fn republishing_requires_fresh_acknowledgment_preserves_evidence(db:PgPool){let h=Harness::new(db).await;let s=h.login().await;let(_,terms,_)=h.request("GET","/terms/applicable",Some(&s),Value::Null).await;let t=&terms[0];let version=t["version_id"].as_str().unwrap();h.request("POST",&format!("/term-versions/{version}/sign"),Some(&s),json!({"typed_name":"Juniper Fox","consent":true,"answers":{},"signature_svg":"<svg><path d=\"M 0,0 L 1,1\"/></svg>"})).await;let term=t["id"].as_str().unwrap();let(_,new,_)=h.request("POST",&format!("/terms/{term}/versions"),Some(&s),json!({"body_markdown":"New fictional version"})).await;assert_eq!(h.request("POST",&format!("/terms/{term}/publish"),Some(&s),json!({"version_id":new["id"]})).await.0,StatusCode::OK);let(_,terms,_)=h.request("GET","/terms/applicable",Some(&s),Value::Null).await;assert!(terms[0]["signed_at"].is_null());let count:i64=sqlx::query_scalar("SELECT count(*) FROM term_signatures WHERE term_version_id=$1::text::uuid").bind(version).fetch_one(&h.db).await.unwrap();assert_eq!(count,1);assert!(sqlx::query("UPDATE term_versions SET body_markdown='changed' WHERE id=$1::text::uuid").bind(version).execute(&h.db).await.is_err());assert!(sqlx::query("DELETE FROM term_signatures").execute(&h.db).await.is_err());}
#[sqlx::test(migrations="./migrations")]async fn volunteers_only_terms_do_not_apply_to_nonvolunteer_staff(db:PgPool){let h=Harness::new(db).await;let s=h.login().await;let(_,terms,_)=h.request("GET","/terms/applicable",Some(&s),Value::Null).await;assert_eq!(terms.as_array().unwrap().len(),1);assert_eq!(terms[0]["audience"],"all");}
#[sqlx::test(migrations="./migrations")]async fn volunteer_submit_qr_approve_records_actor_and_prevents_replay(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let v=h.switch(&hr,"volunteer").await;let(status,b,_)=h.request("POST","/volunteer/entries",Some(&v),json!({"department_id":h.dept("Registration").await,"work_date":chrono::Utc::now().date_naive(),"minutes_worked":90,"work_description":"Registration assistance"})).await;assert_eq!(status,StatusCode::OK,"{b}");let id=b["id"].as_str().unwrap();assert_eq!(h.request("POST",&format!("/volunteer/entries/{id}/submit"),Some(&v),json!({})).await.0,StatusCode::OK);let(_,qr,_)=h.request("POST",&format!("/volunteer/entries/{id}/approval-qr"),Some(&v),json!({})).await;let token=qr["url"].as_str().unwrap().split("?t=").nth(1).unwrap();assert_eq!(h.request("GET",&format!("/volunteer/approval-preview?token={token}"),Some(&v),Value::Null).await.0,StatusCode::FORBIDDEN);let staff=h.switch(&v,"staff").await;let preview=h.request("GET",&format!("/volunteer/approval-preview?token={token}"),Some(&staff),Value::Null).await;assert_eq!(preview.0,StatusCode::OK);let decision=json!({"token":token,"decision":"approve","note":"","idempotency_key":Uuid::new_v4()});assert_eq!(h.request("POST","/volunteer/approval-decisions",Some(&staff),decision.clone()).await.0,StatusCode::OK);assert_eq!(h.request("POST","/volunteer/approval-decisions",Some(&staff),decision).await.0,StatusCode::OK);assert_eq!(h.request("POST","/volunteer/approval-decisions",Some(&staff),json!({"token":token,"decision":"approve","note":"","idempotency_key":Uuid::new_v4()})).await.0,StatusCode::CONFLICT);let actor:Uuid=sqlx::query_scalar("SELECT decided_by_user_id FROM volunteer_entries WHERE id=$1::text::uuid").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(actor,h.id("staff").await);let events:i64=sqlx::query_scalar("SELECT count(*) FROM volunteer_decision_events WHERE entry_id=$1::text::uuid").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(events,1);}
#[sqlx::test(migrations="./migrations")]async fn staff_cannot_approve_own_time_but_any_other_staff_can_preview(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let staff=h.switch(&hr,"staff").await;let id=h.submitted(h.id("staff").await,h.dept("Registration").await).await;let(_,qr,_)=h.request("POST",&format!("/volunteer/entries/{id}/approval-qr"),Some(&staff),json!({})).await;let token=qr["url"].as_str().unwrap().split("?t=").nth(1).unwrap();assert_eq!(h.request("POST","/volunteer/approval-decisions",Some(&staff),json!({"token":token,"decision":"approve","note":"","idempotency_key":Uuid::new_v4()})).await.0,StatusCode::FORBIDDEN);let other=h.switch(&staff,"staff2").await;assert_eq!(h.request("GET",&format!("/volunteer/approval-preview?token={token}"),Some(&other),Value::Null).await.0,StatusCode::OK);}
#[sqlx::test(migrations="./migrations")]async fn qr_expiration_rotation_and_no_mutation_on_get(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let v=h.switch(&hr,"volunteer").await;let id=h.submitted(h.id("volunteer").await,h.dept("Registration").await).await;let(_,qr,_)=h.request("POST",&format!("/volunteer/entries/{id}/approval-qr"),Some(&v),json!({})).await;let first=qr["url"].as_str().unwrap().split("?t=").nth(1).unwrap();let(_,qr,_)=h.request("POST",&format!("/volunteer/entries/{id}/approval-qr"),Some(&v),json!({})).await;let second=qr["url"].as_str().unwrap().split("?t=").nth(1).unwrap();let staff=h.switch(&v,"staff").await;assert_eq!(h.request("GET",&format!("/volunteer/approval-preview?token={first}"),Some(&staff),Value::Null).await.0,StatusCode::CONFLICT);assert_eq!(h.request("GET",&format!("/volunteer/approval-preview?token={second}"),Some(&staff),Value::Null).await.0,StatusCode::OK);let status:String=sqlx::query_scalar("SELECT status FROM volunteer_entries WHERE id=$1").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(status,"submitted");sqlx::query("UPDATE volunteer_approval_tokens SET expires_at=now()-interval '1 second' WHERE entry_id=$1").bind(id).execute(&h.db).await.unwrap();assert_eq!(h.request("GET",&format!("/volunteer/approval-preview?token={second}"),Some(&staff),Value::Null).await.0,StatusCode::CONFLICT);}
#[sqlx::test(migrations="./migrations")]async fn hiring_requires_owner_or_explicit_hr_override_and_is_atomic(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let director=h.switch(&hr,"director").await;let app:Uuid=sqlx::query_scalar("SELECT id FROM applications LIMIT 1").fetch_one(&h.db).await.unwrap();let payload=json!({"decision":"approve","reason":"Good fit after panel review","idempotency_key":Uuid::new_v4()});assert_eq!(h.request("POST",&format!("/applications/{app}/finalize"),Some(&director),payload.clone()).await.0,StatusCode::FORBIDDEN);let owner=h.switch(&director,"lead").await;assert_eq!(h.request("POST",&format!("/applications/{app}/finalize"),Some(&owner),payload.clone()).await.0,StatusCode::OK);assert_eq!(h.request("POST",&format!("/applications/{app}/finalize"),Some(&owner),payload).await.0,StatusCode::OK);let count:i64=sqlx::query_scalar("SELECT count(*) FROM application_final_decisions WHERE application_id=$1").bind(app).fetch_one(&h.db).await.unwrap();assert_eq!(count,1);let n:i64=sqlx::query_scalar("SELECT count(*) FROM user_departments WHERE user_id=$1 AND department_id=$2 AND ended_at IS NULL").bind(h.id("applicant").await).bind(h.dept("Registration").await).fetch_one(&h.db).await.unwrap();assert_eq!(n,1);let n:i64=sqlx::query_scalar("SELECT count(*) FROM permission_grants WHERE user_id=$1 AND permission='settings.manage'").bind(h.id("applicant").await).fetch_one(&h.db).await.unwrap();assert_eq!(n,0);}
#[sqlx::test(migrations="./migrations")]async fn panel_recommendation_does_not_finalize(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let interview:Uuid=sqlx::query_scalar("SELECT id FROM interviews LIMIT 1").fetch_one(&h.db).await.unwrap();assert_eq!(h.request("PUT",&format!("/interviews/{interview}/my-decision"),Some(&hr),json!({"decision":"approve","note":"Great experience"})).await.0,StatusCode::OK);let state:String=sqlx::query_scalar("SELECT status FROM applications LIMIT 1").fetch_one(&h.db).await.unwrap();assert_eq!(state,"interviewing");}
#[sqlx::test(migrations="./migrations")]async fn interview_note_visibility_and_sensitive_answers_do_not_leak(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let interview:Uuid=sqlx::query_scalar("SELECT id FROM interviews LIMIT 1").fetch_one(&h.db).await.unwrap();for visibility in ["author_only","interview_panel","hr"]{assert_eq!(h.request("POST",&format!("/interviews/{interview}/notes"),Some(&hr),json!({"body":format!("{visibility} note"),"visibility":visibility})).await.0,StatusCode::OK);}let lead=h.switch(&hr,"lead").await;let(_,notes,_)=h.request("GET",&format!("/interviews/{interview}/notes"),Some(&lead),Value::Null).await;assert_eq!(notes.as_array().unwrap().len(),1);assert_eq!(notes[0]["visibility"],"interview_panel");let app:Uuid=sqlx::query_scalar("UPDATE applications SET answers_json=answers_json||'{\"accommodations\":\"restricted response\"}'::jsonb RETURNING id").fetch_one(&h.db).await.unwrap();let(_,a,_)=h.request("GET",&format!("/applications/{app}"),Some(&lead),Value::Null).await;assert!(a["answers_json"]["accommodations"].is_null());}
#[sqlx::test(migrations="./migrations")]async fn bulk_snapshot_conflicts_are_reported_and_admin_assignment_is_rejected(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let filter=json!({"op":"eq","field":"display_name","value":"Maple Bunny"});let(status,preview,_)=h.request("POST","/bulk-changes/preview",Some(&hr),json!({"filter":filter,"operation":{"field":"status","value":"inactive"}})).await;assert_eq!(status,StatusCode::OK);assert_eq!(preview["count"],1);sqlx::query("UPDATE users SET updated_at=now()+interval '1 second' WHERE id=$1").bind(h.id("volunteer").await).execute(&h.db).await.unwrap();let(status,result,_)=h.request("POST","/bulk-changes/execute",Some(&hr),json!({"preview_id":preview["id"],"confirmed":true})).await;assert_eq!(status,StatusCode::OK);assert_eq!(result["status"],"partially_failed");assert_eq!(result["results"][0]["status"],"conflict");assert_eq!(h.request("POST","/bulk-changes/preview",Some(&hr),json!({"filter":{"op":"and","args":[]},"operation":{"field":"permissions","value":["settings.manage"]}})).await.0,StatusCode::BAD_REQUEST);}
#[sqlx::test(migrations="./migrations")]async fn bulk_requires_confirmation_and_audits_each_changed_person(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let(_,preview,_)=h.request("POST","/bulk-changes/preview",Some(&hr),json!({"filter":{"op":"eq","field":"display_name","value":"Maple Bunny"},"operation":{"field":"volunteer_eligible","value":false}})).await;assert_eq!(h.request("POST","/bulk-changes/execute",Some(&hr),json!({"preview_id":preview["id"],"confirmed":false})).await.0,StatusCode::BAD_REQUEST);let(status,b,_)=h.request("POST","/bulk-changes/execute",Some(&hr),json!({"preview_id":preview["id"],"confirmed":true})).await;assert_eq!(status,StatusCode::OK,"{b}");assert_eq!(b["status"],"completed");let count:i64=sqlx::query_scalar("SELECT count(*) FROM audit_events WHERE action='people.bulk_updated'").fetch_one(&h.db).await.unwrap();assert_eq!(count,1);assert!(sqlx::query("DELETE FROM audit_events").execute(&h.db).await.is_err());}
#[sqlx::test(migrations="./migrations")]async fn permission_grants_require_system_admin_and_last_admin_cannot_be_removed(db:PgPool){let h=Harness::new(db).await;let hr=h.login().await;let body=json!({"user_id":h.id("volunteer").await,"permission":"people.read","scope_type":"department","scope_id":h.dept("Registration").await});assert_eq!(h.request("POST","/permission-grants",Some(&hr),body.clone()).await.0,StatusCode::FORBIDDEN);let sys=h.switch(&hr,"sys").await;assert_eq!(h.request("POST","/permission-grants",Some(&sys),body).await.0,StatusCode::OK);let id:Uuid=sqlx::query_scalar("SELECT id FROM permission_grants WHERE permission='settings.manage'").fetch_one(&h.db).await.unwrap();assert_eq!(h.request("DELETE",&format!("/permission-grants/{id}"),Some(&sys),json!({})).await.0,StatusCode::CONFLICT);}

#[sqlx::test(migrations="./migrations")]async fn hr_intake_and_finalization_preserve_unverified_identity(db:PgPool){
 let h=Harness::new(db).await;let hr=h.login().await;let post:Uuid=sqlx::query_scalar("SELECT id FROM position_postings WHERE title='Registration team member'").fetch_one(&h.db).await.unwrap();
 let(status,person,_)=h.request("POST","/users",Some(&hr),json!({"display_name":"Aster Test Fox","position_posting_id":post,"unverified_myfwa_id":"UNVERIFIED-123","answers_json":{"motivation":"Welcome everyone","experience":"Community events","availability":"All weekend"}})).await;
 assert_eq!(status,StatusCode::OK,"{person}");let app=person["application_id"].as_str().unwrap();assert_eq!(h.request("POST",&format!("/applications/{app}/finalize"),Some(&hr),json!({"decision":"approve","reason":"Approved following reviewed intake","idempotency_key":Uuid::new_v4()})).await.0,StatusCode::OK);
 let status:String=sqlx::query_scalar("SELECT status FROM users WHERE id=$1::text::uuid").bind(person["id"].as_str().unwrap()).fetch_one(&h.db).await.unwrap();assert_eq!(status,"pending_identity");
 let linked:bool=sqlx::query_scalar("SELECT myfwa_id IS NOT NULL OR dev_identity FROM users WHERE id=$1::text::uuid").bind(person["id"].as_str().unwrap()).fetch_one(&h.db).await.unwrap();assert!(!linked);
 let sessions:i64=sqlx::query_scalar("SELECT count(*) FROM sessions WHERE user_id=$1::text::uuid").bind(person["id"].as_str().unwrap()).fetch_one(&h.db).await.unwrap();assert_eq!(sessions,0);
}
#[sqlx::test(migrations="./migrations")]async fn supervisor_reopen_keeps_immutable_decision_and_snapshot(db:PgPool){
 let h=Harness::new(db).await;let hr=h.login().await;let id=h.submitted(h.id("volunteer").await,h.dept("Registration").await).await;
 sqlx::query("UPDATE volunteer_entries SET status='approved',decided_by_user_id=$2,decided_at=now() WHERE id=$1").bind(id).bind(h.id("hr").await).execute(&h.db).await.unwrap();
 sqlx::query("INSERT INTO volunteer_decision_events(entry_id,actor_user_id,decision,note,method,idempotency_key) VALUES($1,$2,'approved','Original decision','manual',$3)").bind(id).bind(h.id("hr").await).bind(Uuid::new_v4()).execute(&h.db).await.unwrap();
 assert_eq!(h.request("POST",&format!("/volunteer/entries/{id}/reopen"),Some(&hr),json!({"reason":"Correct the recorded duration"})).await.0,StatusCode::OK);
 let original:Value=sqlx::query_scalar("SELECT previous_json FROM volunteer_adjustments WHERE entry_id=$1").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(original["status"],"approved");assert_eq!(original["minutes_worked"],90);
 let count:i64=sqlx::query_scalar("SELECT count(*) FROM volunteer_decision_events WHERE entry_id=$1").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(count,1);assert!(sqlx::query("DELETE FROM volunteer_adjustments").execute(&h.db).await.is_err());
}
