#[sqlx::test(migrations="./migrations")]async fn concurrent_qr_decisions_commit_exactly_one_event(db:PgPool){
 let h=Harness::new(db).await;let initial=h.login().await;let v=h.switch(&initial,"volunteer").await;let id=h.submitted(h.id("volunteer").await,h.dept("Registration").await).await;
 let(_,qr,_)=h.request("POST",&format!("/volunteer/entries/{id}/approval-qr"),Some(&v),json!({})).await;let token=qr["url"].as_str().unwrap().split("?t=").nth(1).unwrap();let staff=h.switch(&v,"staff").await;let hr=h.login().await;
 let(a,b)=tokio::join!(h.request("POST","/volunteer/approval-decisions",Some(&staff),json!({"token":token,"decision":"approve","note":"","idempotency_key":Uuid::new_v4()})),h.request("POST","/volunteer/approval-decisions",Some(&hr),json!({"token":token,"decision":"deny","note":"Concurrent review","idempotency_key":Uuid::new_v4()})));
 assert!((a.0==StatusCode::OK&&b.0==StatusCode::CONFLICT)||(b.0==StatusCode::OK&&a.0==StatusCode::CONFLICT),"{:?} {:?}",a,b);
 let count:i64=sqlx::query_scalar("SELECT count(*) FROM volunteer_decision_events WHERE entry_id=$1").bind(id).fetch_one(&h.db).await.unwrap();assert_eq!(count,1);
}
#[sqlx::test(migrations="./migrations")]async fn concurrent_finalization_is_idempotent(db:PgPool){
 let h=Harness::new(db).await;let hr=h.login().await;let app:Uuid=sqlx::query_scalar("SELECT id FROM applications LIMIT 1").fetch_one(&h.db).await.unwrap();let path=format!("/applications/{app}/finalize");let payload=json!({"decision":"approve","reason":"Reviewed final decision","idempotency_key":Uuid::new_v4()});
 let(a,b)=tokio::join!(h.request("POST",&path,Some(&hr),payload.clone()),h.request("POST",&path,Some(&hr),payload));assert_eq!(a.0,StatusCode::OK,"{a:?}");assert_eq!(b.0,StatusCode::OK,"{b:?}");
 let count:i64=sqlx::query_scalar("SELECT count(*) FROM application_final_decisions WHERE application_id=$1").bind(app).fetch_one(&h.db).await.unwrap();assert_eq!(count,1);
}

