fn request_body(user:Option<Uuid>,department:Option<Uuid>)->Value{json!({"recipient_user_id":user,"recipient_department_id":department,"title":"Help at the welcome desk","body":"Please bring badge stock to desk A.","urgency":"normal","idempotency_key":Uuid::new_v4()})}
#[sqlx::test(migrations="./migrations")]async fn individual_requests_have_private_inboxes_and_explicit_transitions(db:PgPool){
 let h=Harness::new(db).await;let hr=h.login().await;let(status,sent,_)=h.request("POST","/requests",Some(&hr),request_body(Some(h.id("staff").await),None)).await;assert_eq!(status,StatusCode::OK,"{sent}");assert_eq!(sent["recipient_count"],1);assert_eq!(sent["push_queued"],0);
 let id=sent["id"].as_str().unwrap();let staff=h.switch(&hr,"staff").await;let(_,inbox,_)=h.request("GET","/requests?view=inbox",Some(&staff),Value::Null).await;assert_eq!(inbox.as_array().unwrap().len(),1);assert_eq!(inbox[0]["title"],"Help at the welcome desk");
 assert_eq!(h.request("POST",&format!("/requests/{id}/respond"),Some(&staff),json!({"action":"complete"})).await.0,StatusCode::CONFLICT);
 for action in ["accept","complete"]{assert_eq!(h.request("POST",&format!("/requests/{id}/respond"),Some(&staff),json!({"action":action})).await.0,StatusCode::OK);}
 let other=h.switch(&staff,"volunteer2").await;assert_eq!(h.request("GET",&format!("/requests/{id}"),Some(&other),Value::Null).await.0,StatusCode::NOT_FOUND);
 let(_,inbox,_)=h.request("GET","/requests?view=inbox",Some(&other),Value::Null).await;assert!(inbox.as_array().unwrap().is_empty());
}
#[sqlx::test(migrations="./migrations")]async fn team_requests_snapshot_active_members_and_deduplicate_send_retries(db:PgPool){
 let h=Harness::new(db).await;let hr=h.login().await;let body=request_body(None,Some(h.dept("Registration").await));
 let(status,sent,_)=h.request("POST","/requests",Some(&hr),body.clone()).await;assert_eq!(status,StatusCode::OK,"{sent}");assert_eq!(sent["recipient_count"],4);
 let(status,retry,_)=h.request("POST","/requests",Some(&hr),body.clone()).await;assert_eq!(status,StatusCode::OK);assert_eq!(sent["id"],retry["id"]);assert_eq!(retry["replayed"],true);
 let count:i64=sqlx::query_scalar("SELECT count(*) FROM notifications WHERE type='service_request'").fetch_one(&h.db).await.unwrap();assert_eq!(count,4);
 let mut different=body;different["body"]=json!("Changed request with reused key");assert_eq!(h.request("POST","/requests",Some(&hr),different).await.0,StatusCode::CONFLICT);
}
