#[sqlx::test(migrations="./migrations")]async fn request_notifications_queue_real_outbox_jobs_when_push_is_configured(db:PgPool){
 use base64::{Engine,engine::general_purpose::URL_SAFE_NO_PAD};use purrsonnel_api::features::push::PushService;
 let mut h=Harness::new(db).await;
 // Fictional fixture key, never used as a deployment credential. No worker/network call is started.
 let private=URL_SAFE_NO_PAD.encode([7u8;32]);let public=URL_SAFE_NO_PAD.encode(web_push::VapidSignatureBuilder::from_base64_no_sub(&private).unwrap().get_public_key());
 let mut state=AppState::new(sea_orm::SqlxPostgresConnector::from_sqlx_postgres_pool(h.db.clone()),Config{dev_auth:true,origin:"http://localhost:5173".into(),bind:"127.0.0.1:3000".into(),default_user:"dev.hr@purrsonnel.local".into(),max_volunteer_minutes:960});
 state.push=Some(PushService::configured(public,private,"mailto:dev@example.invalid".into()).unwrap());h.router=app::router(state);
 let staff=h.id("staff").await;sqlx::query("INSERT INTO push_subscriptions(user_id,endpoint_hash,endpoint,p256dh,auth) VALUES($1,'fixture','https://fcm.googleapis.com/test','fixture','fixture')").bind(staff).execute(&h.db).await.unwrap();
 let hr=h.login().await;let(status,sent,_)=h.request("POST","/requests",Some(&hr),request_body(Some(staff),None)).await;assert_eq!(status,StatusCode::OK,"{sent}");assert_eq!(sent["push_queued"],1);
 let jobs:i64=sqlx::query_scalar("SELECT count(*) FROM push_deliveries WHERE status='pending'").fetch_one(&h.db).await.unwrap();assert_eq!(jobs,1);
 let(_,other_status,_)=h.request("POST","/push/subscriptions/status",Some(&hr),json!({"endpoint":"https://fcm.googleapis.com/test"})).await;assert_eq!(other_status["active"],false);
 let owner=h.switch(&hr,"staff").await;let(_,own_status,_)=h.request("POST","/push/subscriptions/status",Some(&owner),json!({"endpoint":"https://fcm.googleapis.com/test"})).await;assert_eq!(own_status["active"],false);
 assert_eq!(h.request("DELETE","/push/subscriptions",Some(&owner),json!({"endpoint":"https://fcm.googleapis.com/test"})).await.0,StatusCode::OK);
 let(_,disabled,_)=h.request("POST","/push/subscriptions/status",Some(&owner),json!({"endpoint":"https://fcm.googleapis.com/test"})).await;assert_eq!(disabled["active"],false);
}
