#[sqlx::test(migrations="./migrations")]async fn request_filters_run_before_pagination_without_expanding_visibility(db:PgPool){
 let h=Harness::new(db).await;let hr=h.login().await;
 for (recipient,title,completed) in [(h.id("staff").await,"Badge delivery",true),(h.id("staff").await,"Badge preparation",false),(h.id("staff2").await,"Badge private conversation",true)]{
  let mut body=request_body(Some(recipient),None);body["title"]=json!(title);
  let(status,sent,_)=h.request("POST","/requests",Some(&hr),body).await;assert_eq!(status,StatusCode::OK,"{sent}");
  if completed{sqlx::query("UPDATE service_requests SET status='completed',completed_at=now() WHERE id=$1::text::uuid").bind(sent["id"].as_str().unwrap()).execute(&h.db).await.unwrap();}
 }
 let staff=h.switch(&hr,"staff").await;
 let(status,rows,_)=h.request("GET","/requests?view=inbox&status=completed&q=badge&page_size=1",Some(&staff),Value::Null).await;assert_eq!(status,StatusCode::OK);assert_eq!(rows.as_array().unwrap().len(),1);assert_eq!(rows[0]["title"],"Badge delivery");
 let(_,next,_)=h.request("GET","/requests?view=inbox&status=completed&q=badge&page_size=1&page=2",Some(&staff),Value::Null).await;assert!(next.as_array().unwrap().is_empty());
 let(_,active,_)=h.request("GET","/requests?view=inbox&status=active&q=BADGE",Some(&staff),Value::Null).await;assert_eq!(active.as_array().unwrap().len(),1);assert_eq!(active[0]["title"],"Badge preparation");
}
